from __future__ import annotations

import argparse
import json
import math
from collections import namedtuple
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any
from urllib.parse import parse_qs, urlsplit

from .errors import ChronicleFlowError, NotFoundError, ValidationError
from .service import EVENT_TYPES, ChronicleFlow, _parse_timestamp

TENANT_HEADER = "X-Tenant-Id"

# The only query parameters the metrics query and the Prometheus export
# accept; anything else is a validation error exactly like an unknown field.
METRICS_QUERY_PARAMETERS = ("since", "until")

# The only query parameters the execution events query accepts: a type set, a
# closed time window, and cursor pagination. Anything else is a validation
# error exactly like an unknown field.
EVENTS_QUERY_PARAMETERS = ("types", "since", "until", "cursor", "limit")

# A response rendered as a non-JSON text body (the Prometheus export).
TextResponse = namedtuple("TextResponse", ("content_type", "body"))


def _reject_non_finite(constant: str) -> Any:
    raise ValidationError(f"request body must not contain {constant}")


def _positive_integer(raw: str, name: str) -> int:
    """Parse a query parameter that must be a positive integer."""
    if not raw or not all(character in "0123456789" for character in raw):
        raise ValidationError(f"{name} must be a positive integer")
    value = int(raw)
    if value < 1:
        raise ValidationError(f"{name} must be a positive integer")
    return value


def _assert_finite(value: Any) -> None:
    if isinstance(value, float) and not math.isfinite(value):
        raise ValidationError("request body must not contain non-finite numbers")
    if isinstance(value, dict):
        for item in value.values():
            _assert_finite(item)
    elif isinstance(value, list):
        for item in value:
            _assert_finite(item)


class Handler(BaseHTTPRequestHandler):
    service: ChronicleFlow

    def log_message(self, format: str, *args: Any) -> None:
        return

    def _json(self, status: int, value: Any) -> None:
        body = json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode() + b"\n"
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _write(self, status: int, response: Any) -> None:
        if isinstance(response, TextResponse):
            body = response.body.encode()
            self.send_response(status)
            self.send_header("Content-Type", response.content_type)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self._json(status, response)

    def _metrics_window(self) -> tuple[Any, Any]:
        """Parse the optional since/until query parameters of the metrics routes.

        Both parameters are ISO-8601 UTC timestamps ending in Z, may appear at
        most once, and are the only accepted parameters. Repeating either or
        sending any other parameter is a 400 validation_error.
        """
        query = parse_qs(urlsplit(self.path).query, keep_blank_values=True)
        unknown = [name for name in query if name not in METRICS_QUERY_PARAMETERS]
        if unknown:
            raise ValidationError(f"unknown query parameter: {sorted(unknown)[0]}")
        for name in METRICS_QUERY_PARAMETERS:
            if len(query.get(name, [])) > 1:
                raise ValidationError(f"query parameter {name} must appear at most once")
        return (
            _parse_timestamp(query.get("since", [None])[0], "since"),
            _parse_timestamp(query.get("until", [None])[0], "until"),
        )

    def _events_query(self) -> dict[str, Any]:
        """Parse the optional filter and pagination parameters of the events query.

        ``types`` is a comma-separated set of known event types without empty
        or duplicate entries; ``since`` and ``until`` are ISO-8601 UTC
        timestamps ending in Z; ``cursor`` and ``limit`` are positive
        integers. Every parameter may appear at most once, and any other
        parameter is a 400 validation_error, as is any malformed value.
        """
        query = parse_qs(urlsplit(self.path).query, keep_blank_values=True)
        unknown = [name for name in query if name not in EVENTS_QUERY_PARAMETERS]
        if unknown:
            raise ValidationError(f"unknown query parameter: {sorted(unknown)[0]}")
        for name in EVENTS_QUERY_PARAMETERS:
            if len(query.get(name, [])) > 1:
                raise ValidationError(f"query parameter {name} must appear at most once")
        parsed: dict[str, Any] = {}
        if "types" in query:
            entries = query["types"][0].split(",")
            if any(not entry for entry in entries):
                raise ValidationError("types must be a comma-separated set of event types without empty entries")
            if len(set(entries)) != len(entries):
                raise ValidationError("types must not contain duplicate event types")
            unknown_types = [entry for entry in entries if entry not in EVENT_TYPES]
            if unknown_types:
                raise ValidationError(f"unknown event type: {unknown_types[0]}")
            parsed["types"] = tuple(entries)
        if "since" in query:
            parsed["since"] = _parse_timestamp(query["since"][0], "since")
        if "until" in query:
            parsed["until"] = _parse_timestamp(query["until"][0], "until")
        for name in ("cursor", "limit"):
            if name in query:
                parsed[name] = _positive_integer(query[name][0], name)
        return parsed

    def _body(self) -> Any:
        content_type = self.headers.get("Content-Type", "")
        if content_type.split(";", 1)[0].strip().lower() != "application/json":
            raise ValidationError("Content-Type must be application/json")
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length < 0 or length > 1_000_000:
                raise ValueError
            parsed = json.loads(self.rfile.read(length), parse_constant=_reject_non_finite)
            _assert_finite(parsed)
            return parsed
        except (ValueError, json.JSONDecodeError) as error:
            raise ValidationError("request body must be valid JSON") from error

    def _tenant(self) -> str:
        """Resolve the tenant identifier; an absent header keeps the legacy namespace."""
        if TENANT_HEADER not in self.headers:
            return ""
        tenant = self.headers.get(TENANT_HEADER)
        if not isinstance(tenant, str) or not tenant:
            raise ValidationError(f"{TENANT_HEADER} header must be a non-empty string")
        return tenant

    @staticmethod
    def _instance_index(segment: str) -> int:
        """Parse the element index path segment; a non-integer segment is malformed."""
        digits = segment[1:] if segment.startswith("-") else segment
        if not digits.isdigit():
            raise ValidationError("instance index must be an integer")
        return int(segment)

    def _dispatch(self) -> tuple[int, Any]:
        path = urlsplit(self.path).path
        parts = [part for part in path.split("/") if part]
        if self.command == "GET" and parts == ["health"]:
            return 200, {"status": "ok"}
        if self.command in ("PUT", "POST") and parts == ["quotas"]:
            return 200, self.service.declare_quota(self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if self.command == "GET" and parts == ["quotas"]:
            return 200, self.service.get_quota(self._tenant())
        if self.command == "GET" and parts == ["usage"]:
            return 200, self.service.usage(self._tenant())
        if self.command == "GET" and parts == ["bill"]:
            return 200, self.service.bill(self._tenant())
        if self.command == "GET" and parts == ["metrics"]:
            since, until = self._metrics_window()
            return 200, self.service.metrics(self._tenant(), since, until)
        if self.command == "GET" and parts == ["metrics", "export"]:
            since, until = self._metrics_window()
            return 200, TextResponse(
                "text/plain; version=0.0.4; charset=utf-8",
                self.service.metrics_export(self._tenant(), since, until),
            )
        if self.command == "POST" and parts == ["workflows"]:
            return 201, self.service.create_workflow(self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 2 and parts[0] == "workflows" and self.command == "GET":
            return 200, self.service.get_workflow(parts[1], self._tenant())
        if len(parts) == 3 and parts[0] == "workflows" and parts[2] == "schedule" and self.command == "GET":
            return 200, self.service.schedule_status(parts[1], self._tenant())
        if len(parts) == 3 and parts[0] == "workflows" and parts[2] == "schedule" and self.command in ("POST", "PUT"):
            return 200, self.service.update_schedule(parts[1], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 4 and parts[0] == "workflows" and parts[2] == "schedule" and parts[3] == "pause" and self.command == "POST":
            return 200, self.service.pause_schedule(parts[1], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 4 and parts[0] == "workflows" and parts[2] == "schedule" and parts[3] == "resume" and self.command == "POST":
            return 200, self.service.resume_schedule(parts[1], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if self.command == "POST" and parts == ["executions"]:
            return 201, self.service.create_execution(self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 2 and parts[0] == "executions" and self.command == "GET":
            return 200, self.service.get_execution(parts[1], self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "events" and self.command == "GET":
            return 200, {"events": self.service.events(parts[1], self._tenant(), **self._events_query())}
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "checkpoints" and self.command == "GET":
            return 200, self.service.checkpoints(parts[1], self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "deliveries" and self.command == "GET":
            return 200, self.service.deliveries(parts[1], self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "queues" and self.command == "GET":
            return 200, self.service.queues(parts[1], self._tenant())
        if len(parts) == 5 and parts[0] == "executions" and parts[2] == "queues" and parts[4] == "pull" and self.command == "POST":
            return 200, self.service.pull_queue(parts[1], parts[3], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 5 and parts[0] == "executions" and parts[2] == "queues" and parts[4] == "ack" and self.command == "POST":
            return 200, self.service.ack_queue(parts[1], parts[3], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 5 and parts[0] == "executions" and parts[2] == "maps" and parts[4] in ("expand", "reexpand") and self.command == "POST":
            return 200, self.service.reexpand_map(
                parts[1], parts[3], self._body(), self.headers.get("Idempotency-Key"), self._tenant()
            )
        if len(parts) == 7 and parts[0] == "executions" and parts[2] == "maps" and parts[4] == "instances" and parts[6] == "delete" and self.command == "POST":
            return 200, self.service.delete_map_instance(
                parts[1], parts[3], self._instance_index(parts[5]), self._body(), self.headers.get("Idempotency-Key"), self._tenant()
            )
        if len(parts) == 7 and parts[0] == "executions" and parts[2] == "maps" and parts[4] == "instances" and parts[6] == "modify" and self.command == "POST":
            return 200, self.service.modify_map_instance(
                parts[1], parts[3], self._instance_index(parts[5]), self._body(), self.headers.get("Idempotency-Key"), self._tenant()
            )
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "advance" and self.command == "POST":
            return 200, self.service.advance(parts[1], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "decision" and self.command == "POST":
            return 200, self.service.decision(parts[1], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "migrate" and self.command == "POST":
            return 200, self.service.migrate(parts[1], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "claim" and self.command == "POST":
            return 200, self.service.claim(parts[1], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "heartbeat" and self.command == "POST":
            return 200, self.service.heartbeat(parts[1], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "release" and self.command == "POST":
            return 200, self.service.release(parts[1], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "cancel" and self.command == "POST":
            return 200, self.service.cancel(parts[1], self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "recover" and self.command == "POST":
            return 200, self.service.recover(parts[1], self._body(), self.headers.get("Idempotency-Key"), self._tenant())
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "replay" and self.command == "POST":
            return 200, self.service.replay(parts[1], self._tenant())
        raise NotFoundError("route was not found")

    def _handle(self) -> None:
        try:
            status, response = self._dispatch()
            self._write(status, response)
        except ChronicleFlowError as error:
            self._json(error.status, {"error": {"code": error.code, "message": str(error)}})
        except Exception:
            self._json(500, {"error": {"code": "internal_error", "message": "internal server error"}})

    do_GET = _handle
    do_POST = _handle
    do_PUT = _handle


def main() -> None:
    parser = argparse.ArgumentParser(description="Run the ChronicleFlow HTTP service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", default=8080, type=int)
    parser.add_argument("--database", default="chronicleflow.db")
    arguments = parser.parse_args()
    Handler.service = ChronicleFlow(arguments.database)
    server = ThreadingHTTPServer((arguments.host, arguments.port), Handler)
    print(f"ChronicleFlow listening on http://{arguments.host}:{arguments.port}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from typing import Any

from .errors import ValidationError
from .model import _finite_json

MISSED_POLICIES = ("catch_up", "skip")

# minute, hour, day-of-month, month, day-of-week (0 and 7 are Sunday)
_CRON_RANGES = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 7))


def _parse_cron_field(text: str, low: int, high: int) -> frozenset[int]:
    values: set[int] = set()
    for part in text.split(","):
        if not part:
            raise ValidationError("cron field contains an empty list item")
        base = part
        step = 1
        if "/" in part:
            base, _, step_text = part.rpartition("/")
            if not step_text.isdigit() or int(step_text) <= 0:
                raise ValidationError("cron step must be a positive integer")
            step = int(step_text)
        if base == "*":
            start, end = low, high
        elif "-" in base:
            start_text, _, end_text = base.partition("-")
            if not start_text.isdigit() or not end_text.isdigit():
                raise ValidationError("cron range bounds must be non-negative integers")
            start, end = int(start_text), int(end_text)
            if start > end:
                raise ValidationError("cron range start must not exceed its end")
        else:
            if not base.isdigit():
                raise ValidationError("cron field contains an unparseable item")
            start = end = int(base)
        if start < low or end > high:
            raise ValidationError(f"cron values must be between {low} and {high}")
        values.update(range(start, end + 1, step))
    return frozenset(values)


@dataclass(frozen=True)
class Cron:
    minutes: frozenset[int]
    hours: frozenset[int]
    days_of_month: frozenset[int]
    months: frozenset[int]
    days_of_week: frozenset[int]
    any_day_of_month: bool
    any_day_of_week: bool

    @classmethod
    def parse(cls, raw: Any) -> "Cron":
        if not isinstance(raw, str) or not raw.strip():
            raise ValidationError("cron must be a non-empty string of five fields")
        fields = raw.split()
        if len(fields) != 5:
            raise ValidationError("cron must contain exactly five fields")
        parsed = [_parse_cron_field(text, low, high) for text, (low, high) in zip(fields, _CRON_RANGES)]
        return cls(
            minutes=parsed[0],
            hours=parsed[1],
            days_of_month=parsed[2],
            months=parsed[3],
            days_of_week=parsed[4],
            any_day_of_month=fields[2] == "*",
            any_day_of_week=fields[4] == "*",
        )

    def _day_matches(self, moment: datetime) -> bool:
        day_of_month = moment.day in self.days_of_month
        weekday = moment.isoweekday() % 7  # Sunday is 0, as in cron
        day_of_week = weekday in self.days_of_week or (weekday == 0 and 7 in self.days_of_week)
        if not self.any_day_of_month and not self.any_day_of_week:
            # Standard cron: restricted day-of-month and day-of-week are OR-ed.
            return day_of_month or day_of_week
        return day_of_month and day_of_week

    def matches(self, moment: datetime) -> bool:
        return (
            moment.minute in self.minutes
            and moment.hour in self.hours
            and moment.month in self.months
            and self._day_matches(moment)
        )

    def next_after(self, epoch_seconds: float) -> int | None:
        """Return the epoch seconds of the first matching minute starting strictly
        after epoch_seconds, or None when nothing matches within five years."""
        moment = datetime.fromtimestamp(epoch_seconds, timezone.utc).replace(second=0, microsecond=0)
        moment += timedelta(minutes=1)
        limit = moment + timedelta(days=366 * 5 + 2)
        while moment < limit:
            if moment.month not in self.months:
                moment = (moment.replace(day=1) + timedelta(days=32)).replace(day=1, hour=0, minute=0)
            elif not self._day_matches(moment):
                moment = (moment + timedelta(days=1)).replace(hour=0, minute=0)
            elif moment.hour not in self.hours:
                moment = (moment + timedelta(hours=1)).replace(minute=0)
            elif moment.minute not in self.minutes:
                moment = moment + timedelta(minutes=1)
            else:
                return int(moment.timestamp())
        return None


def parse_schedule(raw: Any) -> dict[str, Any]:
    """Validate a declared schedule and return it normalized.

    A schedule carries exactly an interval in seconds or a five-field cron
    expression (never both), the input used for each created execution, and
    the missed-period policy.
    """
    if not isinstance(raw, dict):
        raise ValidationError("schedule must be an object")
    unknown = set(raw) - {"interval_seconds", "cron", "input", "missed_policy"}
    if unknown:
        raise ValidationError(f"schedule contains unknown fields: {', '.join(sorted(unknown))}")
    missing = {"input", "missed_policy"} - set(raw)
    if missing:
        raise ValidationError(f"schedule is missing fields: {', '.join(sorted(missing))}")
    has_interval = "interval_seconds" in raw
    has_cron = "cron" in raw
    if has_interval and has_cron:
        raise ValidationError("schedule must declare either interval_seconds or cron, not both")
    if not has_interval and not has_cron:
        raise ValidationError("schedule must declare interval_seconds or cron")
    schedule: dict[str, Any] = {}
    if has_interval:
        interval = raw["interval_seconds"]
        if isinstance(interval, bool) or not isinstance(interval, int):
            raise ValidationError("schedule interval_seconds must be a positive integer")
        if interval <= 0:
            raise ValidationError("schedule interval_seconds must be a positive integer")
        schedule["interval_seconds"] = interval
    else:
        # Parsed here so an unparseable or out-of-range expression rejects the
        # whole request; the original text is kept as the declared plan.
        Cron.parse(raw["cron"])
        schedule["cron"] = raw["cron"]
    if not isinstance(raw["input"], dict):
        raise ValidationError("schedule input must be an object")
    _finite_json(raw["input"], "schedule input")
    schedule["input"] = raw["input"]
    policy = raw["missed_policy"]
    if policy not in MISSED_POLICIES:
        raise ValidationError('schedule missed_policy must be "catch_up" or "skip"')
    schedule["missed_policy"] = policy
    return schedule

        # get_execution applies a due timeout first, so termination always
        # takes precedence over recovery.
        state = self.get_execution(execution_id, tenant)
        if state["status"] != "running":
            return state
        row = self.store.connection.execute(
            "SELECT document FROM checkpoints WHERE tenant = ? AND execution_id = ? ORDER BY sequence DESC LIMIT 1",
            (tenant, execution_id),
        ).fetchone()
        if not row:
            raise ConflictError("execution has no checkpoint to recover from")
        try:
            document = self.store.decode(row["document"])
            snapshot = document["state"]
            event_sequence = document["event_sequence"]
        except (ValueError, KeyError, TypeError) as error:
            raise ConflictError("latest checkpoint is not parseable") from error
        if not isinstance(snapshot, dict) or not isinstance(event_sequence, int):
            raise ConflictError("latest checkpoint is not parseable")
        if snapshot != state:
            raise ConflictError("latest checkpoint does not match the materialized state")
        return snapshot

    return self._idempotent(key, f"recover:{execution_id}", apply, tenant)

# --- schedules ------------------------------------------------------

def _schedule_row(self, workflow_id: str, tenant: str = DEFAULT_TENANT) -> Any:
    return self.store.connection.execute(
        "SELECT workflow_id, document, paused, anchor_at, cursor, last_triggered_at, last_execution_id "
        "FROM schedules WHERE tenant = ? AND workflow_id = ?",
        (tenant, workflow_id),
    ).fetchone()

def _assert_workflow_exists(self, workflow_id: str, tenant: str = DEFAULT_TENANT) -> None:
    row = self.store.connection.execute(
        "SELECT 1 FROM workflows WHERE tenant = ? AND id = ?",
        (tenant, workflow_id),
    ).fetchone()
    if not row:
        raise NotFoundError(f"workflow {workflow_id} was not found")

def _schedule_status(self, row: Any) -> dict[str, Any]:
    if row is None:
        # A workflow without a declared schedule has a definite empty result.
        return {"schedule": None}
    return {
        "schedule": self.store.decode(row["document"]),
        "paused": bool(row["paused"]),
        "last_triggered_at": row["last_triggered_at"],
        "last_execution_id": row["last_execution_id"],
    }

def schedule_status(self, workflow_id: str, tenant: str = DEFAULT_TENANT) -> dict[str, Any]:
    with self._operation():
        with self.store.transaction():
            self._assert_workflow_exists(workflow_id, tenant)
            # Settle any due periods first so the answer reflects the
            # schedule as of now, not as of the last background tick.
            self._process_schedules(workflow_id, tenant)
            return self._schedule_status(self._schedule_row(workflow_id, tenant))

@staticmethod
def _empty_body(raw: Any, operation: str) -> None:
    if not isinstance(raw, dict) or raw:
        raise ValidationError(f"{operation} body must be an empty object")

def pause_schedule(
    self, workflow_id: str, raw: Any, key: str | None, tenant: str = DEFAULT_TENANT
) -> dict[str, Any]:
    self._empty_body(raw, "pause schedule")

    def apply() -> dict[str, Any]:
        self._assert_workflow_exists(workflow_id, tenant)
        if self._schedule_row(workflow_id, tenant) is None:
            raise NotFoundError(f"workflow {workflow_id} has no schedule")
        self.store.connection.execute(
            "UPDATE schedules SET paused = 1 WHERE tenant = ? AND workflow_id = ?",
            (tenant, workflow_id),
        )
        return self._schedule_status(self._schedule_row(workflow_id, tenant))

    with self._operation():
        return self._idempotent(key, f"pause-schedule:{workflow_id}", apply, tenant)

def resume_schedule(
    self, workflow_id: str, raw: Any, key: str | None, tenant: str = DEFAULT_TENANT
) -> dict[str, Any]:
    self._empty_body(raw, "resume schedule")

    def apply() -> dict[str, Any]:
        self._assert_workflow_exists(workflow_id, tenant)
        if self._schedule_row(workflow_id, tenant) is None:
            raise NotFoundError(f"workflow {workflow_id} has no schedule")
        self.store.connection.execute(
            "UPDATE schedules SET paused = 0 WHERE tenant = ? AND workflow_id = ?",
            (tenant, workflow_id),
        )
        # Periods that came due while paused are settled immediately
        # according to the missed policy.
        self._process_schedules(workflow_id, tenant)
        return self._schedule_status(self._schedule_row(workflow_id, tenant))

    with self._operation():
        return self._idempotent(key, f"resume-schedule:{workflow_id}", apply, tenant)

def update_schedule(
    self, workflow_id: str, raw: Any, key: str | None, tenant: str = DEFAULT_TENANT
) -> dict[str, Any]:
    # The whole plan is validated before anything is written, so an
    # invalid declaration never partially replaces the stored one.
    schedule = parse_schedule(raw)

    def apply() -> dict[str, Any]:
        self._assert_workflow_exists(workflow_id, tenant)
        self._insert_schedule(workflow_id, schedule, tenant)
        return self._schedule_status(self._schedule_row(workflow_id, tenant))

    with self._operation():
        return self._idempotent(key, f"update-schedule:{workflow_id}", apply, tenant)

def _set_schedule_cursor(self, tenant: str, workflow_id: str, cursor: str) -> None:
    self.store.connection.execute(
        "UPDATE schedules SET cursor = ? WHERE tenant = ? AND workflow_id = ?",
        (cursor, tenant, workflow_id),
    )

def _process_schedules(self, workflow_id: str | None = None, tenant: str | None = None) -> None:
    """Settle every due schedule period once; caller holds a transaction."""
    now = time.time()
    if workflow_id is None:
        rows = self.store.connection.execute(
            "SELECT tenant, workflow_id, document, paused, anchor_at, cursor FROM schedules"
        ).fetchall()
    else:
        rows = self.store.connection.execute(
            "SELECT tenant, workflow_id, document, paused, anchor_at, cursor FROM schedules "
            "WHERE tenant = ? AND workflow_id = ?",
            (tenant or DEFAULT_TENANT, workflow_id),
        ).fetchall()
    for row in rows:
        self._process_schedule(row, now)

def _process_schedule(self, row: Any, now: float) -> None:
    """Advance one schedule to the current time.

    Exactly one execution may exist per schedule period: the trigger row
    and the cursor together make a repeated pass for the same period a
    no-op. While paused nothing fires; a "skip" schedule consumes the
    periods it sleeps through, a "catch_up" schedule keeps them pending
    and fires only the most recent one when it is resumed.
    """
    tenant = row["tenant"]
    workflow_id = row["workflow_id"]
    document = self.store.decode(row["document"])
    paused = bool(row["paused"])
    cursor = row["cursor"]
    if "interval_seconds" in document:
        interval = document["interval_seconds"]
        anchor = row["anchor_at"]
        index = int((now - anchor) // interval)
        if index < 1:
            return
        consumed = int(cursor) if cursor else 0
        if index <= consumed:
            return
        period_key = f"i:{index}"
        fire_at = anchor + index * interval
        granularity = float(interval)
        new_cursor = str(index)
    else:
        cron = Cron.parse(document["cron"])
        candidate = int(cursor) if cursor else cron.next_after(row["anchor_at"])
        horizon = int(now // 60) * 60
        latest = None
        following = candidate
        while following is not None and following <= horizon:
            latest = following
            following = cron.next_after(following)
        if latest is None:
            if candidate is not None and str(candidate) != cursor:
                self._set_schedule_cursor(tenant, workflow_id, str(candidate))
            return
        period_key = f"c:{latest}"
        fire_at = float(latest)
        granularity = 60.0
        # When no further match exists (an unreachable expression), keep
        # scanning from just past the current horizon on later passes.
        new_cursor = str(following) if following is not None else str(horizon + 60)
    if paused:
        if document["missed_policy"] == "skip":
            self._set_schedule_cursor(tenant, workflow_id, new_cursor)
        return
    if document["missed_policy"] == "catch_up" or now - fire_at < granularity:
        fired = self._fire_schedule(tenant, workflow_id, document, period_key)
        if fired is None:
            # The execution quota blocks this period: create nothing and
            # leave the cursor and schedule status untouched so the period
            # is retried on a later pass once capacity exists.
            return
    self._set_schedule_cursor(tenant, workflow_id, new_cursor)

def _fire_schedule(
    self, tenant: str, workflow_id: str, document: dict[str, Any], period_key: str
) -> str | None:
    """Create the execution for one schedule period, or return the existing one.

    Returns None when the tenant's execution quota leaves no room; the
    period then stays pending and the schedule is left unchanged.
    """
    existing = self.store.connection.execute(
        "SELECT execution_id, triggered_at FROM schedule_triggers "
        "WHERE tenant = ? AND workflow_id = ? AND period_key = ?",
        (tenant, workflow_id, period_key),
    ).fetchone()
    if existing:
        execution_id = existing["execution_id"]
        triggered_at = existing["triggered_at"]
    else:
        execution_id = f"{workflow_id}-scheduled-{period_key}"
        claimed = self.store.connection.execute(
            "SELECT 1 FROM executions WHERE tenant = ? AND id = ?",
            (tenant, execution_id),
        ).fetchone()
        if not claimed:
            limits = self._quota_limits(tenant)
            if limits is not None:
                used = self.store.connection.execute(
                    "SELECT COUNT(*) AS used FROM executions WHERE tenant = ?",
                    (tenant,),
                ).fetchone()["used"]
                if used >= limits["executions"]:
                    return None
            # A scheduled run binds the revision that is current at fire
            # time (the unversioned revision for a workflow without
            # versions); later upgrades never move it.
            # The created execution is exactly a manually created one:
            # same state shape and the usual execution_started event,
            # with nothing schedule-specific added to its stream.
            self._insert_execution(execution_id, workflow_id, document["input"], None, None, tenant)
            # A scheduled run counts both as an execution start (recorded
            # by _insert_execution) and as one schedule trigger. A
            # repeated pass for the same period takes the existing-row or
            # already-claimed path and is not metered again.
            self._record_usage(tenant, USAGE_TYPE_SCHEDULE_TRIGGERED)
        triggered_at = self.store.now()
        self.store.connection.execute(
            "INSERT INTO schedule_triggers(tenant, workflow_id, period_key, execution_id, triggered_at) "
            "VALUES (?, ?, ?, ?, ?)",
            (tenant, workflow_id, period_key, execution_id, triggered_at),
        )
    self.store.connection.execute(
        "UPDATE schedules SET last_triggered_at = ?, last_execution_id = ? WHERE tenant = ? AND workflow_id = ?",
        (triggered_at, execution_id, tenant, workflow_id),
    )
    return execution_id

def _node_container(self, workflow: Workflow, state: dict[str, Any], node_id: str) -> tuple[dict[str, Any], dict[str, Any]]:
    """Return the state fragment holding the node's progress and its event context."""
    loop_id = self._active_loop(workflow, state, node_id)

